addPlus("english",{g3:[
 TP("Adverbs","",[
  pg("What Is an Adverb?","Read the big idea. Then circle the adverb.","Know that an adverb tells us more about a verb.",
   CN(["turtle","rabbit"],"An adverb tells us more about a verb. It can tell us how, when, where or how often something happens. The turtle walks slowly. The rabbit hops quickly.","Adverbs"),
   CH("",[["The turtle walks slowly.",["turtle","slowly"],1],["Hina sang sweetly.",["sweetly","Hina"],0],["The wind blew hard.",["wind","hard"],1],["We will go tomorrow.",["tomorrow","go"],0],["The dog barked loudly.",["dog","loudly"],1]])),
  pg("Adding -ly","Turn each describing word into an adverb.","Make adverbs by adding -ly.",
   NO("Many adverbs are made by adding -ly to a describing word: slow becomes slowly."),
   F("",["slow: {{slowly}}","quick: {{quickly}}","soft: {{softly}}","loud: {{loudly}}","careful: {{carefully}}","kind: {{kindly}}","brave: {{bravely}}","quiet: {{quietly}}"],2)),
  pg("Spelling Rules","Sort the words. Do we just add -ly, or change y to i first?","Use the y to i spelling rule for adverbs.",
   NO("If a word ends in y, change the y to i and add -ly: happy becomes happily."),
   SO("",["just add -ly","change y to i, add -ly"],["sad","happy","slow","easy","kind","angry","neat","busy"],[0,1,0,1,0,1,0,1]),
   F("Now write the adverbs.",["happy: {{happily}}","easy: {{easily}}","angry: {{angrily}}","busy: {{busily}}"],2)),
  pg("Adverbs of When","Choose an adverb from the box to finish each sentence.","Use adverbs that tell when.",BK(["yesterday","today","tomorrow","soon","now","later"]),
   F("",["We went to the zoo {{yesterday}}. It was fun.","Please tidy your room {{now}}.","The bus will come {{soon}}, so wait here.","It is Monday {{today}}.","Tomorrow is Friday, so we will visit Nani {{tomorrow}}.","I will finish my homework {{later}}, after dinner."])),
  pg("How, When or Where?","Read the adverb before each sentence. Circle what it tells us.","Sort adverbs by the question they answer.",
   CH("",[["outside: The children played outside.",0],["quickly: Bilal ate his lunch quickly.",0],["early: The train left early.",0],["here: Put your shoes here.",0],["happily: The kitten drank milk happily.",0],["next week: We are going to Murree next week.",0]].map((x,i)=>[x[0],["how","when","where"],[2,0,1,2,0,1][i]]))),
  pg("How Often?","Choose the best adverb for each sentence.","Use adverbs that tell how often.",BK(["always","never","sometimes","often","every day"]),
   F("",["The sun {{always}} rises in the east.","A fish can {{never}} climb a tree.","I brush my teeth {{every day}}.","It {{sometimes}} rains in winter.","We {{often}} eat rice on Sundays, nearly every week."]),
   WR("Write about yourself.",["I always ____________________.","I never ____________________."])),
  pg("Picture Sentences","Look at each picture. Write an adverb from the box.","Choose adverbs that match an action.",BK(["slowly","quickly","quietly","loudly","brightly","carefully"]),
   FP("",[["snail","The snail moves {{slowly}}."],["person-running","Zain runs {{quickly}} in the race."],["sleeping-face","The baby sleeps {{quietly}}."],["speaker-high-volume","The radio plays {{loudly}}."],["sun","The sun shines {{brightly}}."],["test-tube","Hold the glass tube {{carefully}}."]],2)),
  pg("Match the Adverb","Match each sentence start to the best adverb.","Pick adverbs that make sense.",
   MA("Write the letter in the box.",["The thunder crashed","The mouse crept","The cheetah ran","The baby smiled","The tired man yawned"],["loudly","silently","fast","sweetly","sleepily"])),
  pg("Adverb Hunt","Read the story. Then answer the questions.","Find adverbs in a short text.",
   PA("Early in the morning, Sana walked quietly to the garden. She looked carefully under the leaves. A tiny bird was there! It chirped softly. Sana smiled happily and ran inside to tell Dadi. Later, they watched the bird together."),
   F("",["Sana walked {{quietly}} to the garden.","She looked {{carefully}} under the leaves.","The bird chirped {{softly}}.","Sana smiled {{happily}}.","An adverb that tells when: {{early}} or {{later}}"])),
  pg("My Adverb Sentences","Add an adverb to make each sentence better. Then draw one.","Write sentences with adverbs.",
   WR("",["The cat jumped ____________________.","My friend talks ____________________.","We ate our food ____________________.","Write your own sentence with an adverb: ____________________________."]),DR("Draw one of your sentences",200))],
  "Adverbs tell us more about a verb: how (slowly), when (tomorrow), where (outside) and how often (always). Many end in -ly.",
  ["Find the verb first, then ask: how? when? where? how often?","Practise adding -ly and the y to i rule.","Read a story page and hunt for adverbs together."],
  ["Play an adverb game: one person acts, for example walking sleepily, and the others guess the adverb.","Give an order such as clap your hands, then add an adverb: loudly, softly, quickly."],
  "Not every adverb ends in -ly (fast, well, soon), and not every -ly word is an adverb (friendly, lovely are describing words).",
  ["The Quiet Race","A hare and a tortoise had a race. The hare ran quickly, then lay down lazily and fell fast asleep. The tortoise walked slowly but steadily. Soon he crossed the line first! Ask: Find three adverbs that tell how."])
]});

addPlus("maths",{g2:[
 TP("Place value to 1000","",[
  pg("Hundreds, Tens and Ones","Read the big idea. Then fill in the boxes.","Know the value of each digit in a 3-digit number.",
   CN(["abacus","input-numbers"],"A 3-digit number has hundreds, tens and ones. In 345 there are 3 hundreds, 4 tens and 5 ones. 10 ones make 1 ten, and 10 tens make 1 hundred.","Place value"),
   F("",["345 = {{3}} hundreds, {{4}} tens, {{5}} ones","682 = {{6}} hundreds, {{8}} tens, {{2}} ones","507 = {{5}} hundreds, {{0}} tens, {{7}} ones","910 = {{9}} hundreds, {{1}} ten, {{0}} ones"])),
  pg("Build the Number","Write the number.","Make a 3-digit number from hundreds, tens and ones.",
   F("",["2 hundreds + 6 tens + 1 one = {{261}}","4 hundreds + 3 tens + 8 ones = {{438}}","7 hundreds + 0 tens + 5 ones = {{705}}","8 hundreds + 9 tens + 0 ones = {{890}}","1 hundred + 1 ten + 1 one = {{111}}","6 hundreds + 4 ones = {{604}}"],2)),
  pg("Expanded Form","Write each number in parts.","Write numbers in expanded form.",
   NO("472 = 400 + 70 + 2. This is called expanded form."),
   F("",["536 = {{500}} + {{30}} + 6","819 = {{800}} + 10 + {{9}}","264 = 200 + {{60}} + {{4}}","705 = {{700}} + {{5}}","{{358}} = 300 + 50 + 8","{{940}} = 900 + 40"],2)),
  pg("What Is the Digit Worth?","Circle the value of the digit.","Find the value of a digit by its place.",
   CH("",[["In 538, the digit 3 is worth",["3","30","300"],1],["In 721, the digit 7 is worth",["700","70","7"],0],["In 469, the digit 9 is worth",["90","900","9"],2],["In 205, the digit 2 is worth",["20","200","2"],1],["In 683, the digit 8 is worth",["80","8","800"],0]])),
  pg("Compare Numbers","Write <, > or = in each box.","Compare 3-digit numbers using place value.",BK(["<",">","="]),
   NO("Look at the hundreds first. If they are the same, look at the tens, then the ones."),
   F("",["456 {{<}} 465","702 {{>}} 699","380 {{=}} 380","519 {{<}} 591","845 {{>}} 548","300 + 20 {{=}} 320"],2)),
  pg("In Order","Write the numbers from smallest to largest.","Order 3-digit numbers.",
   F("",["309, 390, 39: {{39, 309, 390}}","725, 572, 257: {{257, 572, 725}}","618, 681, 186: {{186, 618, 681}}","444, 404, 440: {{404, 440, 444}}"],1)),
  pg("More and Less","Find 10 more, 10 less, 100 more and 100 less.","Add and take away 10 and 100.",
   F("",["10 more than 245 is {{255}}.","10 less than 380 is {{370}}.","100 more than 516 is {{616}}.","100 less than 704 is {{604}}.","10 more than 695 is {{705}}.","100 more than 900 is {{1000}}."],2)),
  pg("Rupee Notes","Read and solve. Think about place value.","Use hundreds, tens and ones with money.",
   CN(["coin","bank"],"A Rs 100 note is like 1 hundred. A Rs 10 note is like 1 ten. A Rs 1 coin is like 1 one.","Money and place value"),
   WP("",["Abbu has 3 Rs 100 notes, 4 Rs 10 notes and 6 Rs 1 coins. He has Rs {{346}}.","Ammi pays Rs 250 with Rs 100 notes and Rs 10 notes. She uses 2 Rs 100 notes and {{5}} Rs 10 notes.","A toy costs Rs 470. Bilal has 4 Rs 100 notes. He needs Rs {{70}} more.","Nani gives Rs 100 to each of 5 grandchildren. She gives Rs {{500}} in all."])),
  pg("Number Patterns","Find the rule and fill in the missing numbers.","Count on and back in 10s and 100s.",
   F("",["200, 300, {{400}}, 500, {{600}}","650, 660, {{670}}, 680, {{690}}","980, 970, {{960}}, 950, {{940}}","125, 225, {{325}}, 425, {{525}}","790, 800, {{810}}, 820"],1)),
  pg("Number Puzzles","Read the clues. Find the number.","Use place value to solve puzzles.",
   WP("",["I have 7 hundreds, 0 tens and 4 ones. I am {{704}}.","The biggest number I can make with 5, 2 and 8 is {{852}}.","The smallest number I can make with 5, 2 and 8 is {{258}}.","My hundreds digit is 3. My tens digit is double that. My ones digit is 1. I am {{361}}.","I am 10 less than 1000. I am {{990}}."]),
   WR("",["Make your own puzzle: I have ____ hundreds, ____ tens and ____ ones. I am ______."]))],
  "Numbers up to 1000: hundreds, tens and ones, expanded form, comparing and ordering, 10 and 100 more or less, and using rupee notes as a model.",
  ["Use Rs 100, Rs 10 and Rs 1 play money to build numbers.","Say each number in parts: 472 is 400 and 70 and 2.","Compare numbers by looking at the hundreds first."],
  ["Read prices at the shop and say how many hundreds and tens they have.","Roll three dice and make the biggest and smallest number."],
  "Zero matters: 507 has no tens. Children often write 5007 or 57. Use a place value chart with H, T and O columns.",
  ["The Lost Ticket","At the cricket ground, Daniyal's seat number was 3 hundreds, 5 tens and 2 ones. He walked past seat 325 and seat 523. At last he found seat 352! Ask: Why were 325 and 523 the wrong seats?"])
]});

addPlus("science",{g2:[
 TP("Our senses","",[
  pg("Our Five Senses","Read the big idea. Then circle true or false.","Name the five senses.",
   CN(["eye","ear","nose","tongue","hand-with-fingers-splayed"],"We have five senses: sight, hearing, smell, taste and touch. Our senses tell our brain about the world around us.","Five senses"),
   CH("",[["We have five senses.",0],["We taste with our ears.",1],["Our skin helps us feel.",0],["Our senses send messages to the brain.",0],["We smell with our eyes.",1]],TF)),
  pg("Sense Organs","Write the sense under each body part.","Match each sense to its body part.",BK(["see","hear","smell","taste","feel"]),
   FP("",[["eye","We {{see}} with our eyes."],["ear","We {{hear}} with our ears."],["nose","We {{smell}} with our nose."],["tongue","We {{taste}} with our tongue."],["hand-with-fingers-splayed","We {{feel}} with our skin."]],2)),
  pg("Which Sense?","Match each thing to the sense you use most.","Choose the sense we use for different things.",
   MA("Write the letter in the box.",["a rainbow","a ringing bell","a rose","a lemon","a soft teddy bear"],["sight","hearing","smell","taste","touch"])),
  pg("Tastes","Sort the foods by their taste.","Know that foods can be sweet, sour or salty.",
   CN(["lemon","soft-ice-cream","peanuts"],"Our tongue can taste sweet, sour, salty and bitter. Ice cream is sweet. A lemon is sour. Salted peanuts are salty.","Tastes"),
   SO("",["sweet","sour","salty"],["honey","lemon","chips","sugar","imli","salted peanuts"],[0,1,2,0,1,2])),
  pg("Touch and Feel","Circle the word that tells how it feels.","Describe things we touch.",
   CH("",[["A teddy bear feels",["soft","hard"],0],["Ice feels",["hot","cold"],1],["A brick feels",["rough","smooth"],0],["A glass window feels",["rough","smooth"],1],["A cup of hot chai feels",["hot","cold"],0],["A stone feels",["soft","hard"],1]])),
  pg("Senses Keep Us Safe","Write the sense that helps.","Know how our senses warn us of danger.",BK(["see","hear","smell","taste","feel"]),
   F("",["We {{smell}} smoke, so we leave the room.","We {{hear}} a car horn, so we stop.","We {{see}} the red light, so we wait.","We {{taste}} that the milk is sour, so we stop drinking.","We {{feel}} that the pan is hot, so we pull our hand away."])),
  pg("Animal Senses","Read the big idea. Then circle true or false.","Know that animals have strong senses.",
   CN(["owl","dog","snake"],"Some animals have very strong senses. Owls see well at night. Dogs can smell things far away. Snakes flick their tongue to pick up smells.","Animal senses"),
   CH("",[["An owl can see well at night.",0],["A dog has a very good sense of smell.",0],["A snake smells with its tongue.",0],["All animals see colours just like us.",1]],TF)),
  pg("The Mystery Box","Fill in the missing words in the steps of this test.","Plan a simple test using the sense of touch.",BK(["eyes","hands","guess","box"]),
   CY("",[["wrapped-gift","Put a thing in a {{box}}"],["eye","Close your {{eyes}}"],["hand-with-fingers-splayed","Feel it with your {{hands}}"],["thinking-face","Make a {{guess}}"]])),
  pg("Sense Sums","Read and solve.","Use maths to answer questions about senses.",
   WP("",["Ali has 2 eyes and 2 ears. That is {{4}} in all.","A class has 10 children. Each child has 2 eyes. There are {{20}} eyes.","3 children each taste 2 fruits. They taste {{6}} fruits in all.","We have 5 senses. Sana used 3 to eat a mango. She did not use {{2}} senses."])),
  pg("My Senses","Finish the sentences. Then draw.","Describe how you use your senses.",
   WR("",["My favourite smell is ____________________.","A sound I do not like is ____________________.","I use my sense of touch when ____________________.","When I eat a mango, I use these senses: ____________________."]),DR("Draw your favourite food",190))],
  "The five senses (sight, hearing, smell, taste, touch), the body parts we use for each, tastes, how senses keep us safe and how some animals have very strong senses.",
  ["Name each sense and point to the body part.","Close your eyes and use only one sense to guess things.","Talk about how a sense warns us of danger."],
  ["Make a mystery bag with a few things to feel and guess.","Do a taste test with sugar, lemon and salt on a spoon."],
  "Spicy is a feeling of heat, not one of the main tastes. Children may also forget that touch uses the whole skin, not just the hands.",
  ["The Night Walk","One night the lights went out. Hamza could not see, but he heard Ammi calling. He smelled the warm roti and followed the smell to the kitchen. He felt the wall with his hand all the way there. Ask: Which senses did Hamza use?"])
]});

addPlus("history",{g2:[
 TP("The Harappan city","",[
  pg("A City by the River","Read. Then circle true or false.","Know where and when Harappa was built.",
   CN(["brick","houses"],"Harappa was a great city of the Indus Valley. It was built about 4500 years ago beside the Ravi River, in Punjab, Pakistan. Thousands of people lived there.","Harappa"),
   CH("",[["Harappa is in Pakistan.",0],["It was built near the Ravi River.",0],["Harappa was built last year.",1],["Many people lived in Harappa.",0]],TF)),
  pg("Built with Bricks","Read. Then fill in the blanks.","Describe how Harappan people built their city.",BK(["baked","size","streets","wells"]),
   PA("The people of Harappa baked clay bricks in fires. The bricks were all the same shape and size. They built houses along straight streets. Many houses had their own well and a bathroom."),
   F("",["The bricks were {{baked}} in fires.","The bricks were the same shape and {{size}}.","The {{streets}} were straight.","Many houses had their own {{wells}}."])),
  pg("Clean Drains","Read the big idea. Then answer.","Know that Harappa had a drain system.",
   CN(["droplet","shower"],"Harappa had covered drains along the streets. Dirty water from homes flowed into them and away from the city. This kept the city clean.","Drains"),
   CH("",[["What did the drains carry away?",["dirty water","bricks"],0],["Were the drains open or covered?",["covered","open"],0],["Why were drains useful?",["they kept the city clean","they made noise"],0]])),
  pg("Seals and Signs","Read. Then fill in the blanks.","Know what Harappan seals were.",BK(["stone","animals","read","traders"]),
   PA("Harappan people made small square seals from soft stone. The seals had pictures of animals, such as bulls and elephants, and little signs. Traders used them to mark their goods. No one has learned to read the signs yet."),
   F("",["Seals were made of soft {{stone}}.","They had pictures of {{animals}}.","{{traders}} used seals to mark their goods.","We still cannot {{read}} the Harappan signs."])),
  pg("Life in Harappa","Look at each picture. Circle what the Harappan people had.","Know the jobs and things of Harappan life.",
   CP("",[["ox","Ox carts to carry goods",0],["sheaf-of-rice","Wheat and barley from farms",0],["mobile-phone","Mobile phones",1],["amphora","Clay pots and jars",0],["automobile","Cars on the roads",1],["teddy-bear","Clay toys for children",0]],["had","did not have"])),
  pg("Then and Now","Match each Harappan thing to what we use today.","Compare Harappan life with life today.",
   MA("Write the letter in the box.",["ox cart","clay lamp","well","seal","clay toy"],["truck","electric light","tap","stamp","plastic toy"])),
  pg("How We Found It","Put the steps in order. Fill in the missing words.","Know how Harappa was discovered.",BK(["bricks","dig","1920s","museum"]),
   CY("",[["railway-track","Long ago, railway builders took old {{bricks}} from the mounds"],["magnifying-glass-tilted-left","In the {{1920s}}, people saw it was an old city"],["construction-worker","Experts began to {{dig}} carefully"],["classical-building","Seals and pots went to a {{museum}}"]])),
  pg("Harappa Sums","Read and solve.","Use maths with Harappan facts.",
   WP("",["A worker made 20 bricks in the morning and 30 in the afternoon. He made {{50}} bricks.","A trader had 12 seals. He gave 5 away. He had {{7}} seals left.","An ox cart carried 4 jars on each trip. In 3 trips it carried {{12}} jars.","Harappa was built about 4500 years ago. 4500 has {{5}} hundreds."])),
  pg("Facts Quiz","Circle true or false.","Recall facts about Harappa.",
   CH("",[["Harappa and Mohenjo-daro were both Indus Valley cities.",0],["The Harappan people grew cotton.",0],["The bricks were all different sizes.",1],["The city had covered drains.",0],["We can read Harappan writing easily.",1],["Children in Harappa played with clay toys.",0]],TF)),
  pg("A Day in Harappa","Imagine you lived in Harappa. Finish the sentences and draw.","Write about life in an ancient city.",
   WR("",["My house is made of ____________________.","My job is to ____________________.","I like my city because ____________________."]),DR("Draw a Harappan street",210))],
  "Harappa, a great Indus Valley city built about 4500 years ago by the Ravi River in Punjab: baked bricks, straight streets, covered drains, seals, farming and trade.",
  ["Find Harappa near Sahiwal on a map of Pakistan.","Talk about how the city stayed clean without modern pipes.","Compare Harappan things with what we use today."],
  ["Make a seal from clay or dough and press an animal picture into it.","Visit the Lahore Museum or look at photos of Harappan seals."],
  "Children may think Harappa and Mohenjo-daro are the same city. They are two cities of the same Indus Valley people, far apart.",
  ["The Little Seal Maker","Long ago in Harappa, a boy helped his father carve seals from soft stone. One day he carved a big bull. A trader liked it so much that he used it to mark all his cotton bundles. Ask: What did the trader use the seal for?"])
]});

